<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$slug=trim($_GET['slug']??''); $stmt=db()->prepare("SELECT * FROM products WHERE slug=? AND status='published' LIMIT 1"); $stmt->execute([$slug]); $product=$stmt->fetch();
if(!$product){http_response_code(404);exit('محصول پیدا نشد.');}
$images=db()->prepare('SELECT image_path,alt_text FROM product_images WHERE product_id=? ORDER BY is_primary DESC,sort_order');$images->execute([$product['id']]);$images=$images->fetchAll();
$cats=db()->prepare('SELECT c.name,c.slug FROM categories c JOIN product_categories pc ON pc.category_id=c.id WHERE pc.product_id=? AND c.is_active=1');$cats->execute([$product['id']]);$cats=$cats->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($product['name'])?></title><link rel="stylesheet" href="/assets/style.css"><body><header class="site-header"><a class="brand" href="/">CRIVIT</a><nav><a href="/">خانه</a><a href="/admin/login.php">مدیریت</a></nav></header><main class="container"><div class="product-detail"><div class="gallery"><?php foreach($images as $image):?><img src="<?=e($image['image_path'])?>" alt="<?=e($image['alt_text']??$product['name'])?>"><?php endforeach?><?php if(!$images):?><div class="image-placeholder">CRIVIT</div><?php endif?></div><div><h1><?=e($product['name'])?></h1><p><?=e($product['summary']??'')?></p><?php if($product['sale_price']!==null):?><p class="old-price"><?=number_format((float)$product['price'])?> تومان</p><?php endif?><h2><?=number_format((float)($product['sale_price']??$product['price']))?> تومان</h2><p><?=nl2br(e($product['description']??''))?></p><p><?=((int)$product['stock_quantity']>0)?'موجود':'ناموجود'?></p><div class="category-tags"><?php foreach($cats as $c):?><a href="/category.php?slug=<?=rawurlencode($c['slug'])?>"><?=e($c['name'])?></a><?php endforeach?></div></div></div></main></body></html>
